 {'k':'SVO','p':'*özne + fiil + nesne*','e':('She *wrote a letter*.','Mektup yazdı.')},
 {'k':'SVC','p':'*özne + linking verb + tümleç*','e':('He *became angry*.','Sinirlendi.')},
 {'k':'SVOO','p':'*özne + fiil + kişi + şey*','e':('He *gave her a book*.','Ona kitap verdi.')},
 {'k':'SVOC','p':'*özne + fiil + nesne + tümleç*','e':('They *elected him president*.','Onu başkan seçtiler.')},
